const items = $input.all();

// Separar bundle y actos
const bundleItem = items.find(i => i.json.correction_prompt);
const actItems = items.filter(i => i.json.act_number !== undefined);

if (!bundleItem) {
  throw new Error("No se encontró prompt_bundle");
}

if (actItems.length === 0) {
  throw new Error("No hay actos");
}

const bundle = bundleItem.json;

// Fan-out manual (equivalente a multiplex)
return actItems.map(act => {
  return {
    json: {
      ...act.json,
      correction_prompt: bundle.correction_prompt,
    }
  };
});

const data = $json;

// Validaciones mínimas
if (!data.correction_prompt) {
  throw new Error("Falta correction_prompt");
}

if (!data.chapter) {
  throw new Error("Falta chapter");
}

// Inyección
const actHeader = `ACTO ${data.act_number}:\n`;
const prompt = data.correction_prompt.replace(
  /{{text}}/g,
  actHeader + data.chapter
);

// Output mínimo (token-efficient + persistencia ready)
return [
  {
    json: {
      id_story: data.id_story,
      act_number: data.act_number,
      prompt
    }
  }
];

const inputData = $input.all();

const result = inputData.map(item => {
    const text = item.json.text;

    // Extraer corrected_text usando regex
    const match = text.match(/"corrected_text"\s*:\s*"(.*)"/s);
    if (match) {
        return {
            corrected_text: match[1].replace(/\\n/g, '\n')
        };
    }
    return null;
}).filter(Boolean);

return result;

const data = $json;

// Validaciones
if (!data.relato) {
  throw new Error("Falta full_text");
}

if (!data.detection_prompt) {
  throw new Error("Falta detection_prompt");
}

// Inyección
let prompt = data.detection_prompt.replace(/{{text}}/g, data.relato.trim());

// Output mínimo
return [
  {
    json: {
      prompt
    }
  }
];

const raw = $json.text || "";

// ---------------------------------------------------------
// 1. LIMPIEZA
// ---------------------------------------------------------
const cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// ---------------------------------------------------------
// 2. PARSEO ROBUSTO
// ---------------------------------------------------------
let parsed;

try {
  parsed = JSON.parse(cleaned);
} catch {
  const match = cleaned.match(/\{[\s\S]*\}/);

  if (!match) {
    return [{
      json: {
        id_story: $json.id_story,
        issues: [],
        warning: "No se pudo parsear JSON de detection"
      }
    }];
  }

  try {
    parsed = JSON.parse(match[0]);
  } catch {
    return [{
      json: {
        id_story: $json.id_story,
        issues: [],
        warning: "JSON inválido en detection"
      }
    }];
  }
}

// ---------------------------------------------------------
// 3. VALIDACIÓN
// ---------------------------------------------------------
if (!parsed.issues || !Array.isArray(parsed.issues)) {
  return [{
    json: {
      id_story: $json.id_story,
      issues: [],
      warning: "No se encontraron issues válidos"
    }
  }];
}

// ---------------------------------------------------------
// 4. NORMALIZACIÓN MEJORADA
// ---------------------------------------------------------
const normalizedIssues = parsed.issues.map((issue, index) => {

  // 🔴 FIX CLAVE: soportar múltiples nombres de campo
  const location =
    issue.location ||
    issue.act_location ||
    issue.act ||
    "unknown";

  return {
    id: index + 1, // útil para debugging y resolución
    type: issue.type || "unknown",
    description: issue.description || "",
    location,
    severity: normalizeSeverity(issue.severity)
  };
});

// ---------------------------------------------------------
// 5. NORMALIZACIÓN DE SEVERIDAD
// ---------------------------------------------------------
function normalizeSeverity(sev) {
  if (!sev) return "media";

  const s = sev.toLowerCase();

  if (s.includes("alta")) return "alta";
  if (s.includes("baja")) return "baja";

  return "media";
}

// ---------------------------------------------------------
// 6. OUTPUT
// ---------------------------------------------------------
return [{
  json: {
    id_story: $json.id_story,
    relato: $json.relato,
    resolution_prompt: $json.resolution_prompt,
    validation_prompt: $json.validation_prompt,
    issues: normalizedIssues
  }
}];

const relato = $json.relato;
const issues = $json.issues || [];
const template = $json.resolution_prompt;

// ---------------------------------------------------------
// 1. Validaciones
// ---------------------------------------------------------
if (!relato) {
  throw new Error("Falta relato en build_resolution_prompt");
}

if (!template) {
  throw new Error("Falta resolution_prompt");
}

// ---------------------------------------------------------
// 2. Si no hay issues → skip inteligente
// ---------------------------------------------------------
if (issues.length === 0) {
  return [{
    json: {
      id_story: $json.id_story,
      relato,
      skip_resolution: true
    }
  }];
}

// ---------------------------------------------------------
// 3. Serializar issues correctamente
// ---------------------------------------------------------
const issuesString = JSON.stringify(issues, null, 2);

// ---------------------------------------------------------
// 4. Construir prompt
// ---------------------------------------------------------
let prompt = template
  .replace(/{{text}}/g, relato.trim())
  .replace(/{{issues}}/g, issuesString);

// ---------------------------------------------------------
// 5. Output completo (NO perder contexto)
// ---------------------------------------------------------
return [{
  json: {
    id_story: $json.id_story,
    relato,
    validation_prompt: $json.validation_prompt,
    prompt,
    issues
  }
}];

// 1. INPUT
const raw = $json.text;

if (!raw) {
  return [{ json: { sanitized_text: "", warning: "Input vacío" }}];
}

// 2. EXTRAER SOLO EL JSON (entre ```json ... ```)
const match = raw.match(/```json\s*([\s\S]*?)\s*```/);

if (!match) {
  return [{ json: { sanitized_text: "", warning: "No se encontró bloque JSON" }}];
}

let jsonString = match[1].trim();

// 3. PARSEAR DIRECTO (sin hacks raros)
let parsed;

try {
  parsed = JSON.parse(jsonString);
} catch (e) {
  return [{ 
    json: { 
      sanitized_text: "", 
      warning: "JSON inválido incluso tras extracción",
      debug: jsonString.slice(0, 200)
    }
  }];
}

// 4. OUTPUT LIMPIO
return [{
  json: {
    act_number: $json.act_number, // IMPORTANTE para aggregate
    id_story: $json.id_story,
    sanitized_text: parsed.sanitized_text || ""
  }
}];

const data = $json;

// Validaciones duras
if (!data.sanitized_text) {
  throw new Error("Falta sanitized_text");
}

if (!data.validation_prompt) {
  throw new Error("Falta validation_prompt");
}

// Inyección
let prompt = data.validation_prompt
  .replace(/{{text}}/g, data.sanitized_text.trim());

// Output limpio
return [
  {
    json: {
      prompt
    }
  }
];

// ---------------------------------------------------------
// 1. EXTRACCIÓN
// ---------------------------------------------------------
// Obtenemos la respuesta. Normalmente vendrá en $json.output si usaste Output Parser,
// o en $json.text si es respuesta cruda.
const raw = $json.output || $json.text || "";

if (!raw) {
  return [{ json: { is_valid: false, notes: "Error: No se recibió respuesta del validador." } }];
}

// ---------------------------------------------------------
// 2. LIMPIEZA DE MARKDOWN
// ---------------------------------------------------------
let cleaned = raw
  .replace(/```json/g, "")
  .replace(/```/g, "")
  .trim();

// ---------------------------------------------------------
// 3. EXTRACCIÓN DEL JSON
// ---------------------------------------------------------
// Buscamos el objeto JSON completo entre las llaves { ... }
const match = cleaned.match(/\{[\s\S]*\}/);

if (!match) {
  return [{ json: { is_valid: false, notes: "Error: Formato JSON no encontrado en validación." } }];
}

let parsed;
try {
  parsed = JSON.parse(match[0]);
} catch (e) {
  // Si falla el parseo, asumimos lo peor para no pasar un relato corrupto
  return [{ json: { is_valid: false, notes: "Error: JSON inválido en respuesta de validación." } }];
}

// ---------------------------------------------------------
// 4. NORMALIZACIÓN DE DATOS
// ---------------------------------------------------------
// Aseguramos que is_valid sea un booleano real, no un string "true"/"false"
let isValid = parsed.is_valid;

if (typeof isValid === 'string') {
  isValid = isValid.toLowerCase() === 'true';
}

// Aseguramos que existan las notas
let notes = parsed.notes || "";

// ---------------------------------------------------------
// 5. OUTPUT
// ---------------------------------------------------------
// Mantenemos el id_story para los siguientes pasos de Persistencia
return [
  {
    json: {
      id_story: $json.id_story, // Preservamos el ID
      is_valid: isValid,        // Será TRUE o FALSE (booleano)
      notes: notes
    }
  }
];

const items = $input.all();

let correction = "";
let detection = "";
let resolution = "";
let validation = "";

// Config (último item)
const config = items.find(i => i.json.id_story)?.json;

if (!config) {
  throw new Error("No se encontró config con id_story");
}

for (let i = 0; i < items.length; i++) {

  const item = items[i];

  if (!item.binary || !item.binary.data) {
    continue;
  }

  const fileName = item.binary.data.fileName;

  const buffer = await this.helpers.getBinaryDataBuffer(i, "data");
  const text = buffer.toString("utf8").trim();

  if (fileName === config.correction_prompt_file) {
    correction = text;
    continue;
  }

  if (fileName === config.detection_prompt_file) {
    detection = text;
    continue;
  }

  if (fileName === config.resolution_prompt_file) {
    resolution = text;
    continue;
  }

  if (fileName === config.validation_prompt_file) {
    validation = text;
    continue;
  }
}

// Validación
if (!correction || !detection || !resolution || !validation) {
  throw new Error("Faltan prompts. Revisar nodo Read Files");
}

return [
  {
    json: {
      id_story: config.id_story,
      correction_prompt: correction,
      detection_prompt: detection,
      resolution_prompt: resolution,
      validation_prompt: validation
    }
  }
];

// ---------------------------------------------------------
// 1. OBTENER DATOS
// ---------------------------------------------------------
const data = $json;

const idStory = data.id_story || "sin_id";

// ---------------------------------------------------------
// 2. GESTIÓN DE VERSIÓN (Auto-incremental simulado)
// ---------------------------------------------------------
// Como el nodo Code no recuerda ejecuciones pasadas, necesitamos
// que la versión venga de un nodo "Postgres: get_next_version".
//
// Si existe el campo 'version' en el input, úsalo. Si no, asume v1.
const version = data.version || 1;

// ---------------------------------------------------------
// 3. CONTENIDO DEL ARCHIVO
// ---------------------------------------------------------
// Usamos directamente el texto sanitizado completo, sin separar en actos.
const storyContent = data.sanitized_text || "";

// ---------------------------------------------------------
// 4. NOMBRE DE ARCHIVO Y SALIDA
// ---------------------------------------------------------
// Formato solicitado: id_story + _saneado_version_X.md
const fileName = `${idStory}_saneado_version_${version}.md`;

// Retornamos el objeto listo para el nodo "Convert to File" o "Write File"
return {
  json: {
    file_name: fileName,
    markdown_content: storyContent
  }
};

// Loop over input items and add a new field called 'myNewField' to the JSON of each one
for (const item of $input.all()) {
  item.json.myNewField = 1;
}

return $input.all();

const items = $input.all();

let acts = [];

for (const item of items) {
  acts.push({
    act_number: item.json.act_number || 0,
    content: item.json.sanitized_text || ""
  });
}

// ordenar por número de acto
acts.sort((a, b) => a.act_number - b.act_number);

// construir markdown final
const fullText = acts
  .map(a => `## Acto ${a.act_number}\n\n${a.content}`)
  .join("\n\n");

return [
  {
    json: {
      id_story: items[0].json.id_story,
      sanitized_text: fullText
    }
  }
];

const items = $input.all();

if (items.length === 0) {
  throw new Error("No hay datos de correction");
}

// 1. Mapear y asignar act_number por orden
const structured = items.map((item, index) => {
  const text = item.json.corrected_text || "";

  return {
    act_number: index + 1,
    chapter: text.trim()
  };
});

// 2. Output directo (array de items)
return structured.map(el => ({
  json: el
}));

const items = $input.all();

// ordenar por act_number
const acts = items
  .map(i => i.json)
  .sort((a, b) => a.act_number - b.act_number);

const output = [];

for (let i = 0; i < acts.length; i++) {

  const current = acts[i];
  const prev = acts[i - 1];
  const next = acts[i + 1];

  // ventana principal (current + next)
  let windowActs = [];

  if (current) {
    windowActs.push(`ACTO-${current.act_number}\n${current.chapter}`);
  }

  if (next) {
    windowActs.push(`ACTO-${next.act_number}\n${next.chapter}`);
  }

  const context_window = windowActs.join("\n\n");

  output.push({
    json: {
      id_story: current.id_story,
      detection_prompt: current.detection_prompt,

      act_number: current.act_number,

      current_act: current.chapter,
      prev_act: prev ? prev.chapter : "",
      next_act: next ? next.chapter : "",

      context_window
    }
  });
}

return output;
